from game.lessons import unit as U

LESSONS = {
1: [
 U("Una tabla responde preguntas", "La universidad guarda un estudiante por fila. Para encontrar un dato cruzamos esa fila con una columna, como en una lista de asistencia.", "SELECT id, nombre, semestre\nFROM estudiantes;", "Observa los registros reales\nUna fila reúne los datos de una persona\nCada columna representa una característica", error="Una fila no es una columna, nombre es una característica y Carlos es un valor de esa característica", check="¿Qué dato obtienes al cruzar la fila de Carlos con semestre?"),
 U("Elegir qué mostrar", "SELECT nombra las columnas que queremos ver y FROM indica dónde buscarlas. Las comas separan columnas, no van después de la última.", "SELECT nombre, oficina\nFROM profesores;", "SELECT: qué información quieres\nFROM: en qué tabla está\nEl punto y coma cierra la sentencia", error="SELECT nombre, FROM profesores tiene una coma sobrante antes de FROM"),
 U("Explorar todas las columnas", "El asterisco pide todas las columnas. Resulta útil para explorar una tabla. Cuando necesitas solo un par de datos conviene nombrarlos.", "SELECT *\nFROM profesores;", "El resultado consulta los registros almacenados\nNo mueve ni elimina información\nSin ORDER BY no prometemos un orden"),
 U("Ver las repeticiones", "Si mostramos el estado de cada estudiante veremos Activo muchas veces. Porque esa característica puede repetirse entre personas distintas. Todavía tenemos una fila por estudiante.", "SELECT estado\nFROM estudiantes;", "El mismo valor puede aparecer en varias filas\nEso no significa que sean el mismo estudiante"),
 U("Categorías sin repetir", "Si solo necesitamos conocer qué estados existen. DISTINCT devuelve cada estado una sola vez. Compara con la lista anterior, las filas originales siguen guardadas.", "SELECT DISTINCT estado\nFROM estudiantes;", "DISTINCT actúa sobre el resultado completo\nSi eliges dos columnas, compara la pareja", check="Si dos personas comparten carrera pero tienen nombres distintos, ¿DISTINCT nombre, carrera las combina?")],
2: [
 U("Encontrar a quienes cumplen una condición", "Podríamos revisar todos los estudiantes a mano. Pero si necesitamos los de un semestre concreto podemos pedirle a SQLite que revise la condición en cada fila.", "SELECT nombre, semestre, promedio\nFROM estudiantes\nWHERE semestre = 2;", "WHERE conserva las filas cuya condición es verdadera\nsemestre es la columna, = compara con el valor 2"),
 U("Comparar un promedio", "Busquemos promedios superiores a 5,5. SELECT decide qué columnas vemos, FROM elige estudiantes y WHERE compara el promedio de cada persona con el límite.", "SELECT nombre, promedio\nFROM estudiantes\nWHERE promedio > 5.5;", "El signo > significa mayor que\n5.5 es un número, no necesita comillas", check="¿Valentina aparece si su promedio es exactamente 5,5?"),
 U("Incluir el valor del límite", "Ahora añadimos el signo igual. Valentina también entra porque >= acepta tanto los valores mayores como el propio 5,5. El resto de la consulta se mantiene.", "SELECT nombre, promedio\nFROM estudiantes\nWHERE promedio >= 5.5;", "> deja fuera el límite, >= lo incluye\n< y <= hacen lo mismo hacia los valores menores", error="Confundir > con >= puede dejar fuera a quien está justo en el límite"),
 U("Comparar palabras", "Una columna puede contener texto. Para buscar un estado escribimos su valor entre comillas simples. Sin esas comillas SQLite intentaría interpretarlo como un nombre.", "SELECT nombre, estado\nFROM estudiantes\nWHERE estado = 'Suspendido';", "estado es el nombre de una columna\n'Suspendido' es el valor de texto que buscamos", error="No confundas un identificador con un literal de texto, usa el valor exacto del catálogo"),
 U("Cumplir dos condiciones con AND", "Necesitamos personas de segundo semestre con promedio al menos 5,5. Ignacio, Valentina, Camila y Lucas cumplen la primera condición. Lucas queda fuera porque no cumple la segunda.", "SELECT nombre, semestre, promedio\nFROM estudiantes\nWHERE semestre = 2 AND promedio >= 5.5;", "AND necesita que ambas condiciones sean verdaderas\nComprueba cada condición por separado y luego juntas"),
 U("Aceptar alternativas con OR", "Si basta estar en segundo semestre o tener promedio al menos 6,8. Usamos OR. Sofía y Constanza pueden entrar por el promedio aunque estén en otro semestre.", "SELECT nombre, semestre, promedio\nFROM estudiantes\nWHERE semestre = 2 OR promedio >= 6.8;", "OR acepta una condición o las dos\nNo duplica a quien cumple ambas", check="¿Por qué esta consulta puede devolver más personas que la anterior?"),
 U("Agrupar decisiones con paréntesis", "Queremos estudiantes activos que estén en primer o cuarto semestre. Encerramos la alternativa para exigir Activo en ambos casos. Sin paréntesis AND se evalúa antes que OR.", "SELECT nombre, semestre, estado\nFROM estudiantes\nWHERE estado = 'Activo'\n  AND (semestre = 1 OR semestre = 4);", "Primero decide la alternativa entre paréntesis\nDespués exige que también se cumpla Activo", error="estado = 'Activo' AND semestre = 1 OR semestre = 4 también acepta suspendidos de cuarto semestre", check="¿Qué cambiarías para incluir segundo semestre en la alternativa?")],
3: [
 U("Dar un orden explícito", "Sin una indicación de orden no podemos confiar en qué fila aparecerá primero. Ordenemos a los profesores por nombre para preparar una lista de asistencia.", "SELECT nombre, oficina\nFROM profesores\nORDER BY nombre ASC;", "ORDER BY define el criterio de orden\nASC va de menor a mayor y es la opción por defecto"),
 U("Números en ambas direcciones", "Para repartir las salas podemos revisar primero las materias con más créditos. DESC invierte el sentido. El orden cambia, pero los registros almacenados siguen iguales.", "SELECT codigo, creditos\nFROM materias\nORDER BY creditos DESC, codigo ASC;", "DESC: mayor a menor\nSi empatan en créditos, codigo ASC resuelve el empate", error="Con un solo criterio los empates no tienen un orden garantizado", check="¿Qué cambiarías para ver primero las de menos créditos?"),
 U("Filtrar antes de ordenar", "Ahora solo interesan las materias con ocho o más cupos. WHERE decide cuáles participan y ORDER BY organiza esas mismas filas.", "SELECT nombre, cupos\nFROM materias\nWHERE cupos >= 8\nORDER BY cupos DESC, nombre ASC;", "WHERE elige las filas\nORDER BY organiza el resultado elegido")],
4: [
 U("Una página pequeña", "El catálogo puede ser largo. LIMIT pide un máximo de filas. Si solo hay una coincidencia y pedimos dos recibimos una, nunca se inventan registros.", "SELECT nombre, oficina\nFROM profesores\nORDER BY nombre ASC\nLIMIT 2;", "LIMIT 2 significa hasta dos filas\nEl orden explícito define cuáles son las primeras", error="LIMIT no significa mejores, ese criterio lo define ORDER BY"),
 U("Pasar a la página siguiente", "OFFSET salta filas del resultado ordenado. Como ya vimos las dos primeras ahora saltamos dos. Quedan menos profesores que el máximo solicitado.", "SELECT nombre, oficina\nFROM profesores\nORDER BY nombre ASC\nLIMIT 2 OFFSET 2;", "Primero ordenamos, luego saltamos y limitamos\nUn orden estable evita páginas ambiguas", check="¿Qué OFFSET usarías para la tercera página de dos filas?"),
 U("Construir una consulta por partes", "Para revisar materias con al menos cuatro créditos filtramos primero. Después ordenamos por cupos y nombre. Por último mostramos una página pequeña.", "SELECT nombre, cupos\nFROM materias\nWHERE creditos >= 4\nORDER BY cupos DESC, nombre ASC\nLIMIT 2;", "SELECT columnas, FROM tabla, WHERE condición\nORDER BY criterio, LIMIT máximo\nPuedes probar cada paso antes de añadir el siguiente")]
}
